import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] totals = new long[2];
        long mx = Long.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            long v = nextLong();
            totals[i % 2] += Math.max(v, 0);  // a merged value only combines same-parity originals
            mx = Math.max(mx, v);
        }
        long best = Math.max(totals[0], totals[1]);
        System.out.println(best > 0 ? best : mx);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"math"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	var totals [2]int64
	mx := int64(math.MinInt64)
	for i := 0; i < n; i++ {
		v := nextInt()
		totals[i%2] += max(v, 0) // a merged value only combines same-parity originals
		mx = max(mx, v)
	}
	best := max(totals[0], totals[1])
	if best > 0 {
		fmt.Println(best)
	} else {
		fmt.Println(mx)
	}
